custom_css:
/* MoodTube × MoonThemes Moon Retro — окна Windows 98, как в теме таверны */
:root, [data-mt-theme="custom"] {
    --r-face: #c0c0c0; --r-light: #dfdfdf; --r-white: #ffffff; --r-shadow: #808080; --r-dark: #0a0a0a;
    --r-field: #ffffff; --r-ink: #000000; --r-muted: #404040; --r-dim: #707070; --r-link: #0000ee; --r-navy: #000080; --r-hold: #e8e8f4;
    --r-title: linear-gradient(90deg, #000080, #1084d0);
    --r-title-off: linear-gradient(90deg, #808080, #b5b5b5);
    --r-raised: inset -1px -1px var(--r-dark), inset 1px 1px var(--r-white), inset -2px -2px var(--r-shadow), inset 2px 2px var(--r-light);
    --r-pressed: inset -1px -1px var(--r-white), inset 1px 1px var(--r-dark), inset -2px -2px var(--r-light), inset 2px 2px var(--r-shadow);
    --r-sunken: inset -1px -1px var(--r-white), inset 1px 1px var(--r-shadow), inset -2px -2px var(--r-light), inset 2px 2px var(--r-dark);
    --r-window: inset -1px -1px var(--r-dark), inset 1px 1px var(--r-light), inset -2px -2px var(--r-shadow), inset 2px 2px var(--r-white);
    --r-font: Tahoma, Verdana, 'Noto Sans', 'Segoe UI', sans-serif;

    /* Ползунки — Win98: утопленная дорожка и прямоугольный бегунок */
    --mt-slider-track: var(--r-field);
    --mt-slider-track-height: 4px;
    --mt-slider-track-radius: 0;
    --mt-slider-thumb-size: 14px;
    --mt-slider-thumb-radius: 0;
    --mt-slider-thumb-bg: var(--r-face);
    --mt-slider-thumb-bg-hover: var(--r-face);
    --mt-slider-thumb-border: none;
    --mt-slider-thumb-shadow: var(--r-raised);
    --mt-slider-progress: var(--r-navy);

    --mt-overlay: rgba(0, 0, 0, 0.35);
    --mt-modal-shadow: var(--r-window), 4px 4px 0 rgba(0, 0, 0, 0.45);
    --mt-dock-cover-radius: 0;
    --mt-dock-height: 40px;
    --mt-pl-spotify-tab: var(--r-navy);
    --mt-pl-spotify-tab-text: #fff;
}

/* ===== Окно плеера ===== */
.mt-player, .mt-player *, .mt-fab, .mt-dock, .mt-dock *, #mt-settings-modal *, .mt-pl-modal * { font-family: var(--r-font); }
.mt-player {
    background: var(--r-face);
    border: none;
    border-radius: 0;
    box-shadow: var(--r-window), 4px 4px 0 rgba(0, 0, 0, 0.45);
    backdrop-filter: none; -webkit-backdrop-filter: none;
    padding: 34px 12px 12px;
    color: var(--r-ink);
    cursor: default;
}
/* Заголовок окна */
.mt-player-header {
    top: 3px; left: 3px; right: 3px; height: 20px;
    padding: 0 88px 0 6px; box-sizing: border-box;
    align-items: center; gap: 4px;
    background: var(--r-title);
    color: #fff; font-size: 12px; font-weight: 700;
}
.mt-player.mt-is-idle .mt-player-header { background: var(--r-title-off); }
.mt-player-header-title { color: #fff; }
.mt-player-header-title::before { content: '♪ '; }
.mt-player-status { color: #fff; opacity: 0.85; font-size: 12px; font-weight: 400; }
.mt-player-status::before { content: '— '; }
/* Кнопки заголовка (поиск, настройки, закрыть) */
.mt-player .mt-window-btn {
    top: 6px; width: 16px; height: 14px;
    display: flex; align-items: center; justify-content: center;
    background: var(--r-face); box-shadow: var(--r-raised);
    color: var(--r-ink); font-size: 9px;
}
.mt-player .mt-window-btn:active { box-shadow: var(--r-pressed); }
.mt-player .mt-btn-close { right: 6px; }
.mt-player .mt-btn-settings { right: 24px; }
.mt-player .mt-btn-search { right: 42px; }
.mt-player .mt-btn-lyrics { right: 60px; }
.mt-player .mt-window-btn:hover, .mt-player .mt-btn-search.mt-is-open { color: var(--r-ink); transform: none; }
.mt-player .mt-btn-search.mt-is-open { box-shadow: var(--r-pressed); }

/* Обложка — утопленная рамка */
.mt-cover {
    border: none; border-radius: 0; padding: 2px; box-sizing: border-box;
    background: var(--r-field); box-shadow: var(--r-sunken);
}
.mt-cover-img { border-radius: 0; }
.mt-cover-hole { display: none; }
.mt-player.moodtube-row-layout .mt-cover { border-width: 0; }

.mt-track-title { font-size: 13px; font-weight: 700; color: var(--r-ink); }
.mt-track-subtitle { font-size: 11px; font-weight: 400; color: var(--r-muted); }
.mt-time { color: var(--r-muted); font-size: 11px; }

/* Кнопки управления — выпуклые квадраты */
.mt-player .mt-btn:hover, .mt-dock .mt-dock-btn:hover { transform: none; }
.mt-controls { gap: 4px; }
.mt-controls .mt-btn {
    width: 30px; height: 24px; box-sizing: border-box;
    display: inline-flex; align-items: center; justify-content: center;
    background: var(--r-face); box-shadow: var(--r-raised);
    color: var(--r-ink); font-size: 12px;
}
.mt-controls .mt-btn:hover { color: var(--r-ink); }
.mt-controls .mt-btn:active, .mt-controls .mt-btn-ai.mt-is-busy { box-shadow: var(--r-pressed); }
.mt-controls .mt-btn-play { width: 40px; height: 28px; font-size: 14px; }
.mt-controls .mt-btn-accent { color: var(--r-ink); }
.mt-btn-ai.mt-is-busy { color: var(--r-link); }
.mt-btn-favorite {
    width: 18px; height: 18px; display: flex; align-items: center; justify-content: center;
    background: var(--r-face); box-shadow: var(--r-raised); color: var(--r-ink); font-size: 10px;
}
.mt-btn-favorite.mt-is-active { color: #c00000; box-shadow: var(--r-pressed); }
.mt-player .mt-btn-lyrics.mt-is-open { color: var(--r-ink) !important; box-shadow: var(--r-pressed); }
/* Текст песни */
.mt-lyric-line { color: var(--r-ink); font-size: 12px; }
.mt-lyric-line.mt-is-active { color: var(--r-ink); background: var(--r-hold); transform: none; }
.mt-lyrics-body { background: var(--r-field); box-shadow: var(--r-sunken); }
.mt-lyrics-message i { color: var(--r-ink); }
.mt-volume-icon { color: var(--r-ink); }

/* ===== Очередь, плейлисты, поиск ===== */
.mt-panel { inset: 26px 3px 3px 3px; padding: 8px; background: var(--r-face); }
.mt-panel-header-left { margin-right: 0; }
.mt-panel-title { color: var(--r-ink); font-size: 12px; }
.mt-panel .mt-btn { color: var(--r-ink); }
.mt-panel-list { background: var(--r-field); box-shadow: var(--r-sunken); padding: 3px; }
.mt-queue-item {
    margin: 0; padding: 4px 6px; gap: 8px;
    background: transparent; border: 1px dotted transparent; border-radius: 0;
}
.mt-queue-item:hover { background: var(--r-hold); }
.mt-queue-item.mt-is-current { background: var(--r-navy); border-color: var(--r-ink); }
.mt-queue-item.mt-is-current .mt-queue-title, .mt-queue-item.mt-is-current .mt-queue-now, .mt-queue-item.mt-is-current .mt-pl-count, .mt-queue-item.mt-is-current .mt-queue-add { color: #fff; }
.mt-queue-add { color: var(--r-ink); }
.mt-queue-title { color: var(--r-ink); font-size: 12px; }
.mt-queue-thumb { border-radius: 0; box-shadow: var(--r-sunken); padding: 1px; box-sizing: border-box; }
.mt-queue-empty { color: var(--r-dim); }
.mt-pl-section-title { color: var(--r-muted); }
.mt-pl-section-add { color: var(--r-link); }
.mt-pl-cover { border-radius: 0; }
.mt-pl-cover-fav { background: var(--r-navy); color: #fff; }
.mt-pl-tabs { background: var(--r-face); padding: 0; gap: 2px; }
.mt-pl-tab, .mt-pl-tool, .mt-pl-inline-ok, .mt-pl-inline-cancel {
    border-radius: 0; border: none; background: var(--r-face); box-shadow: var(--r-raised); color: var(--r-ink);
}
.mt-pl-tab.mt-is-active, .mt-pl-tab[data-mt-tab="spotify"].mt-is-active { background: var(--r-face); color: var(--r-ink); box-shadow: var(--r-pressed); }
.mt-pl-tool.mt-pl-play { background: var(--r-face); color: var(--r-ink); border: none; font-weight: 700; }
.mt-pl-tool:active, .mt-pl-inline-ok:active { box-shadow: var(--r-pressed); }
.mt-pl-inline-ok { background: var(--r-face); color: var(--r-ink); }
.mt-pl-inline-input { --mt-pl-input-bg: var(--r-field); --mt-pl-input-border: transparent; }
#moodtube-mini-player .mt-pl-inline .mt-pl-inline-input, #moodtube-add-playlist-modal .mt-pl-inline .mt-pl-inline-input { border-radius: 0 !important; box-shadow: var(--r-sunken) !important; }
#moodtube-mini-player .mt-pl-inline button, #moodtube-add-playlist-modal .mt-pl-inline button { border-radius: 0 !important; box-shadow: var(--r-raised) !important; }
.mt-panel-search { background: var(--r-face) !important; }
#moodtube-search-container #moodtube-search-input { border-radius: 0 !important; border: none !important; box-shadow: var(--r-sunken) !important; background: var(--r-field) !important; }
#moodtube-search-container #moodtube-search-go { border-radius: 0 !important; background: var(--r-face) !important; box-shadow: var(--r-raised) !important; color: var(--r-ink) !important; }

/* Окно «Добавить в плейлист» */
.mt-pl-modal-box { border: none; border-radius: 0; background: var(--r-face); box-shadow: var(--r-window), 4px 4px 0 rgba(0, 0, 0, 0.45); padding: 3px; }
.mt-pl-modal-header { background: var(--r-title); padding: 3px 4px 3px 6px; color: #fff; }
.mt-pl-modal-title { font-size: 12px; color: #fff; }
.mt-pl-modal-close {
    width: 16px; height: 14px; display: flex; align-items: center; justify-content: center;
    background: var(--r-face); box-shadow: var(--r-raised); color: var(--r-ink); font-size: 9px;
}
.mt-pl-modal-track { padding: 6px; border-bottom: none; color: var(--r-muted); }
.mt-pl-modal-body { background: var(--r-field); box-shadow: var(--r-sunken); margin: 0 4px 4px; padding: 3px; }
.mt-pl-option { border-radius: 0; background: transparent; margin: 0; }
.mt-pl-option:hover { background: var(--r-hold); }
.mt-pl-option.mt-is-added .mt-pl-option-icon { color: var(--r-link); }

/* ===== Плавающая кнопка ===== */
.mt-fab {
    border: none; border-radius: 0;
    background: var(--r-face); box-shadow: var(--r-raised), 3px 3px 0 rgba(0, 0, 0, 0.45);
    color: var(--r-ink); font-size: 16px;
}
.mt-fab.mt-is-playing { box-shadow: var(--r-pressed), 3px 3px 0 rgba(0, 0, 0, 0.45); }
#moodtube-fab.mt-playing::before { display: none; }

/* ===== Шапка сверху ===== */
.mt-dock { background: var(--r-face); border-bottom: none; box-shadow: var(--r-raised); backdrop-filter: none; -webkit-backdrop-filter: none; color: var(--r-ink); }
.mt-dock-inner { gap: 8px; padding: 5px 8px 11px; }
.mt-dock-cover { border: none; padding: 2px; background: var(--r-field); box-shadow: var(--r-sunken); }
.mt-dock-title { font-size: 12px; font-weight: 700; color: var(--r-ink); }
.mt-dock-subtitle { font-size: 11px; font-weight: 400; color: var(--r-muted); }
.mt-dock-controls { gap: 3px; }
.mt-dock-btn {
    width: 24px; height: 22px; box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center;
    background: var(--r-face); box-shadow: var(--r-raised); color: var(--r-ink); font-size: 11px;
}
.mt-dock-btn:hover { color: var(--r-ink); }
.mt-dock-btn:active, .mt-dock-queue.mt-is-open, .mt-dock-expand.mt-is-open, .mt-dock-ai.mt-is-busy { box-shadow: var(--r-pressed); color: var(--r-ink); text-shadow: none; }
.mt-dock-play { width: 30px; font-size: 12px; }
.mt-dock-fav.mt-is-active { color: #c00000; }
/* Полоса хода — Win98 прогресс-бар из блоков */
.mt-dock-progress { left: 8px; right: 8px; bottom: 3px; height: 6px; background: var(--r-field); box-shadow: var(--r-sunken); }
.mt-dock-progress-fill { margin: 1px; height: calc(100% - 2px); background: repeating-linear-gradient(90deg, var(--r-navy) 0 6px, transparent 6px 8px); }

/* ===== Окно настроек — диалог Win98 ===== */
#mt-settings-modal .mt-flex-container { background: var(--r-face); border: none; border-radius: 0; padding: 3px; color: var(--r-ink); }
#mt-settings-modal .mt-header { background: var(--r-title); border-bottom: none; padding: 3px 4px 3px 8px; }
#mt-settings-modal .mt-header h3 { color: #fff; font-size: 13px; font-weight: 700; letter-spacing: 0; }
#mt-settings-modal .mt-header-icon { color: #fff; }
#mt-settings-modal .mt-close {
    width: 16px; height: 14px; display: flex; align-items: center; justify-content: center;
    background: var(--r-face); box-shadow: var(--r-raised); color: var(--r-ink); font-size: 9px;
}
#mt-settings-modal .mt-close:active { box-shadow: var(--r-pressed); }
#mt-settings-modal .mt-content { padding: 10px; }
#mt-settings-modal .mt-category { background: var(--r-face); border: none; border-radius: 0; box-shadow: var(--r-sunken); }
#mt-settings-modal .mt-cat-title:hover { background: transparent; }
#mt-settings-modal .mt-cat-title h4 { color: var(--r-ink); font-size: 12px; text-transform: none; letter-spacing: 0; font-weight: 700; }
#mt-settings-modal .mt-cat-title i:first-child { color: var(--r-ink); }
#mt-settings-modal .mt-chevron { color: var(--r-ink); }
#mt-settings-modal .mt-label { color: var(--r-muted); }
#mt-settings-modal .mt-label-accent { color: var(--r-ink); font-weight: 700; }
#mt-settings-modal .mt-input-field { background: var(--r-field); border: none; border-radius: 0; box-shadow: var(--r-sunken); color: var(--r-ink); }
#mt-settings-modal .mt-input-field:focus { background: var(--r-field); outline: 1px dotted var(--r-ink); outline-offset: -4px; }
#mt-settings-modal .mt-btn-test, #mt-settings-modal .mt-btn-save {
    border: none; border-radius: 0; background: var(--r-face); box-shadow: var(--r-raised); color: var(--r-ink); filter: none;
}
#mt-settings-modal .mt-btn-save { box-shadow: 0 0 0 1px var(--r-dark), var(--r-raised); font-weight: 700; }
#mt-settings-modal .mt-btn-test:active, #mt-settings-modal .mt-btn-save:active { box-shadow: var(--r-pressed); }
#mt-settings-modal .mt-tag { border: none; border-radius: 0; background: var(--r-face); box-shadow: var(--r-raised); color: var(--r-ink); }
#mt-settings-modal .mt-tag.active { background: var(--r-navy); color: #fff; box-shadow: var(--r-pressed); }
#mt-settings-modal .mt-footer { background: var(--r-face); border-top: 1px solid var(--r-shadow); }
#mt-settings-modal .mt-summary-tag { border-radius: 0; background: var(--r-navy); color: #fff; box-shadow: none; }
#mt-settings-modal .mt-subpanel { background: var(--r-face); border: none; border-radius: 0; box-shadow: var(--r-raised); }
#mt-settings-modal .mt-divider { border-top: 1px solid var(--r-shadow); box-shadow: 0 1px 0 var(--r-white); }
#mt-settings-modal code { background: var(--r-field); border-radius: 0; }
#mt-settings-modal .mt-catalog-card { border: none; border-radius: 0; background: var(--r-face); box-shadow: var(--r-raised); }
#mt-settings-modal .mt-catalog-preview { box-shadow: var(--r-sunken); }
#mt-settings-modal .mt-catalog-filter { border-radius: 0; border: none; background: var(--r-face); box-shadow: var(--r-raised); color: var(--r-ink); }
#mt-settings-modal .mt-catalog-filter.mt-is-active { background: var(--r-navy); color: #fff; box-shadow: var(--r-pressed); }
#mt-settings-modal .mt-content::-webkit-scrollbar { width: 16px; background: var(--r-light); }
#mt-settings-modal .mt-content::-webkit-scrollbar-thumb { background: var(--r-face); box-shadow: var(--r-raised); border-radius: 0; }
#mt-settings-modal .mt-content::-webkit-scrollbar-track { background: repeating-conic-gradient(var(--r-face) 0 25%, var(--r-white) 0 50%) 0 0 / 2px 2px; }
.mt-panel-list::-webkit-scrollbar { width: 16px; background: var(--r-light); }
.mt-panel-list::-webkit-scrollbar-thumb { background: var(--r-face); box-shadow: var(--r-raised); border-radius: 0; }
.mt-panel-list::-webkit-scrollbar-track { background: repeating-conic-gradient(var(--r-face) 0 25%, var(--r-white) 0 50%) 0 0 / 2px 2px; }
